49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    private final IdempotencyKeyRegistry idempotencyKeyRegistry;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper,
79	                                 IdempotencyKeyRegistry idempotencyKeyRegistry) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	        this.idempotencyKeyRegistry = idempotencyKeyRegistry;
85	    }
86	
87	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
88	    @Override
89	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
90	        Collection<Owner> owners;
91	        if (lastName != null) {
92	            owners = this.clinicService.findOwnerByLastName(lastName);
93	        } else {
94	            owners = this.clinicService.findAllOwners();
95	        }
96	        if (owners.isEmpty()) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
105	        Owner owner = this.clinicService.findOwnerById(ownerId);
106	        if (owner == null) {
107	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
108	        }
109	        return new ResponseEntity<>(toOwnerDtoWithWarning(owner), HttpStatus.OK);
110	    }
111	
112	    /** Map an owner to its DTO, setting the read-only {@code bulkSignupWarning} flag the same way
113	     *  for every owner response. */
114	    private OwnerDto toOwnerDtoWithWarning(Owner owner) {
115	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
116	        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupDay());
117	        return ownerDto;
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
123	        // A create retried with an already-seen idempotency key returns the originally created
124	        // owner with 200, rather than creating a duplicate.
125	        Integer existingId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey).orElse(null);
126	        if (existingId != null) {
127	            Owner existing = this.clinicService.findOwnerById(existingId);
128	            if (existing != null) {
129	                return new ResponseEntity<>(toOwnerDtoWithWarning(existing), HttpStatus.OK);
130	            }
131	        }
132	        HttpHeaders headers = new HttpHeaders();
133	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
134	        AddressValidator.validate(owner.getAddress());
135	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
136	        DisposableEmailValidator.validate(owner.getEmail());
137	        RegistrationDateValidator.validate(owner.getRegistrationDate());
138	        if (this.clinicService.isDailyRegistrationAtCapacity()) {
139	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
140	        }
141	        // The household id is deterministic from (lastName, postcode), so owners sharing a last name
142	        // and postcode are automatically the same household.
143	        owner.setHouseholdId(this.clinicService.householdIdFor(owner.getLastName(), owner.getPostcode()));
144	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
145	        // A second owner in an existing household is a duplicate unless it declares itself a member,
146	        // which bypasses the household duplicate block.
147	        if (!sharesHousehold && this.clinicService.isHouseholdInUse(owner)) {
148	            return new ResponseEntity<>(HttpStatus.CONFLICT);
149	        }
150	        // Reject exact identity duplicates: when the new owner's whole identity key
151	        // (telephone|email|householdId) matches an existing one.
152	        if (this.clinicService.isIdentityKeyInUse(owner)) {
153	            return new ResponseEntity<>(HttpStatus.CONFLICT);
154	        }
155	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
156	            return new ResponseEntity<>(HttpStatus.CONFLICT);
157	        }
158	        this.clinicService.saveOwner(owner, sharesHousehold);
159	        this.idempotencyKeyRegistry.remember(idempotencyKey, owner.getId());
160	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
161	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
162	            ownerMapper.formatMembershipLevel(owner), ownerMapper.formatMembershipNumber(owner));
163	        OwnerDto ownerDto = toOwnerDtoWithWarning(owner);
164	        headers.setLocation(UriComponentsBuilder.newInstance()
165	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
166	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
172	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
173	        if (currentOwner == null) {
174	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
175	        }
176	        PostcodeValidator.validate(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
177	        DisposableEmailValidator.validate(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
178	        ownerMapper.applyAddressFields(ownerFieldsDto, currentOwner);
179	        AddressValidator.validate(currentOwner.getAddress());
180	        currentOwner.setCity(ownerFieldsDto.getCity());
181	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
182	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
183	        currentOwner.setLastName(ownerFieldsDto.getLastName());
184	        currentOwner.setTitle(ownerMapper.mapTitle(ownerFieldsDto.getTitle()));
185	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
186	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
187	        this.clinicService.saveOwner(currentOwner);
188	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Transactional
193	    @Override
194	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
195	        Owner owner = this.clinicService.findOwnerById(ownerId);
196	        if (owner == null) {
197	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
198	        }
199	        this.clinicService.deleteOwner(owner);
200	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
206	        Owner owner = this.clinicService.findOwnerById(ownerId);
207	        if (owner == null) {
208	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	        }
210	        HttpHeaders headers = new HttpHeaders();
211	        Pet pet = petMapper.toPet(petFieldsDto);
212	        owner.setId(ownerId);
213	        pet.setOwner(owner);
214	        pet.getType().setName(null);
215	        this.clinicService.savePet(pet);
216	        PetDto petDto = petMapper.toPetDto(pet);
217	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
218	            .buildAndExpand(pet.getId()).toUri());
219	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
220	    }
221	
222	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
223	    @Override
224	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
225	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
226	        if (currentOwner != null) {
227	            Pet currentPet = this.clinicService.findPetById(petId);
228	            if (currentPet != null) {
229	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
230	                currentPet.setName(petFieldsDto.getName());
231	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
232	                this.clinicService.savePet(currentPet);
233	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
234	            }
235	        }
236	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
237	    }
238	
239	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
240	    @Override
241	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
242	        HttpHeaders headers = new HttpHeaders();
243	        Visit visit = visitMapper.toVisit(visitFieldsDto);
244	        Pet pet = new Pet();
245	        pet.setId(petId);
246	        visit.setPet(pet);
247	        this.clinicService.saveVisit(visit);
248	        VisitDto visitDto = visitMapper.toVisitDto(visit);
249	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
250	            .buildAndExpand(visit.getId()).toUri());
251	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
252	    }
253	
254	
255	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
256	    @Override
257	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
258	        Owner owner = this.clinicService.findOwnerById(ownerId);
259	        if (owner != null) {
260	            Pet pet = owner.getPet(petId);
261	            if (pet != null) {
262	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
263	            }
264	        }
265	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
266	    }
267	}
