28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "title")
40	    private String title;
41	
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "address_line1")
47	    private String addressLine1;
48	
49	    @Column(name = "address_line2")
50	    private String addressLine2;
51	
52	    @Column(name = "city")
53	    @NotEmpty
54	    private String city;
55	
56	    @Column(name = "postcode")
57	    private String postcode;
58	
59	    @Column(name = "telephone")
60	    @NotEmpty
61	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
62	    private String telephone;
63	
64	    @Column(name = "email")
65	    @Email
66	    private String email;
67	
68	    @Column(name = "registration_date")
69	    private LocalDate registrationDate;
70	
71	    @Column(name = "birth_date")
72	    private LocalDate birthDate;
73	
74	    @Column(name = "customer_code")
75	    private String customerCode;
76	
77	    @Column(name = "household_id")
78	    private String householdId;
79	
80	    @Column(name = "namesake_count")
81	    private Integer namesakeCount;
82	
83	    @Column(name = "possible_duplicate")
84	    private Boolean possibleDuplicate;
85	
86	    @Column(name = "possible_duplicate_of")
87	    private Integer possibleDuplicateOf;
88	
89	    @Column(name = "deleted", nullable = false)
90	    private boolean deleted = false;
91	
92	    /**
93	     * The current number of owners that belong to this owner's household (owners sharing the same
94	     * {@code householdId}, including this one). Not persisted: it is populated from the current data
95	     * whenever the owner is loaded or saved.
96	     */
97	    @Transient
98	    private Integer householdMemberCount;
99	
100	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
101	    private Set<Pet> pets;
102	
103	    public String getTitle() {
104	        return this.title;
105	    }
106	
107	    public void setTitle(String title) {
