239	    /**
240	     * The owner's derived identity key, {@code normalizedTelephone + '|' + (email or empty) + '|' +
241	     * (householdId or empty)}. This single key is the sole criterion for duplicate detection on
242	     * creation: a new owner is rejected with 409 only when its whole identity key equals an existing
243	     * owner's. Because the telephone is part of the key, two members of the same household (same
244	     * {@code householdId}) with different telephones have distinct identity keys and are both
245	     * allowed; only an exact full-key match is a duplicate. The telephone and email components are
246	     * already held in their normalized forms (canonical E.164 and lower-cased) on every write path,
247	     * so the key is comparable across owners. Not persisted: it is computed from the current fields.
248	     */
249	    @Transient
250	    public String getIdentityKey() {
251	        String telephoneOrEmpty = this.telephone == null ? "" : this.telephone;
252	        String emailOrEmpty = this.email == null ? "" : this.email;
253	        String householdOrEmpty = this.householdId == null ? "" : this.householdId;
254	        return telephoneOrEmpty + "|" + emailOrEmpty + "|" + householdOrEmpty;
255	    }
256	
257	    /**
258	     * Stamp the owner's registration date with the server's current date on first
259	     * persist when none was supplied, so the default applies on every create path.
260	     */
261	    @PrePersist
262	    protected void onCreate() {
263	        if (this.registrationDate == null) {
264	            this.registrationDate = LocalDate.now();
265	        }
266	    }
267	
268	    protected Set<Pet> getPetsInternal() {
