267	    @Override
268	    @Transactional
269	    public void saveOwner(Owner owner, boolean declaredHouseholdMember) throws DataAccessException {
270	        if (owner.isNew()) {
271	            LocalDate effectiveDate = owner.getRegistrationDate() != null
272	                ? owner.getRegistrationDate()
273	                : LocalDate.now();
274	            owner.setRegistrationDate(toBusinessDay(effectiveDate));
275	            if (owner.getHouseholdId() == null) {
276	                owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
277	            }
278	            if (owner.getCustomerCode() == null) {
279	                owner.setCustomerCode(generateCustomerCode(owner));
280	            }
281	            if (owner.getNamesakeCount() == null) {
282	                owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
283	            }
284	            if (owner.getPossibleDuplicate() == null) {
285	                // A declared household member is not a suspected duplicate; otherwise flag it against
286	                // any existing member of the same household it collides with.
287	                Integer possibleDuplicateOf = declaredHouseholdMember ? null : findPossibleDuplicateOf(owner);
288	                owner.setPossibleDuplicateOf(possibleDuplicateOf);
289	                owner.setPossibleDuplicate(possibleDuplicateOf != null);
290	            }
291	        }
292	        ownerRepository.save(owner);
293	        decorateWithHouseholdMemberCount(owner);
294	    }
295	
296	    /**
297	     * Count the existing owners (before this create) that share the given first and last name,
298	     * compared case-insensitively, as required by the read-only {@code namesakeCount} field.
299	     */
300	    private int countNamesakes(String firstName, String lastName) {
301	        if (firstName == null || lastName == null) {
302	            return 0;
303	        }
304	        return (int) ownerRepository.findAll().stream()
305	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
306	                && lastName.equalsIgnoreCase(owner.getLastName()))
307	            .count();
308	    }
309	
310	    /**
311	     * Build a customer code formatted {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
312	     * canonical region derived from the owner's postcode (falling back to the city-to-region
313	     * table, then {@code 'UNKNOWN'}, as resolved by {@link LocalityResolver}) and {@code HASH8}
314	     * is the first 8 upper-case hexadecimal characters of the SHA-256 digest over the owner's
315	     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}).
316	     * <p>
317	     * If the computed code collides with an existing owner's {@code customerCode}, it is
318	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
319	     * makes it unique (e.g. {@code 'NSW-1A2B3C4D-2'}).
320	     */
321	    private String generateCustomerCode(Owner owner) {
322	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
323	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
324	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
325	        String base = region + "-" + Sha256Hex.upperHexPrefix(telephone + lastName, 8);
326	
327	        Set<String> existingCodes = ownerRepository.findAll().stream()
328	            .map(Owner::getCustomerCode)
329	            .filter(Objects::nonNull)
330	            .collect(Collectors.toSet());
331	        if (!existingCodes.contains(base)) {
332	            return base;
333	        }
334	        int n = 2;
335	        while (existingCodes.contains(base + "-" + n)) {
336	            n++;
337	        }
338	        return base + "-" + n;
339	    }
