372	    /**
373	     * Count the owners whose registration date equals today's business day, used by the
374	     * daily create-limit and bulk-signup rules.
375	     */
376	    private long countRegisteredToday() {
377	        LocalDate businessDay = toBusinessDay(LocalDate.now());
378	        return ownerRepository.findAll().stream()
379	            .filter(owner -> businessDay.equals(owner.getRegistrationDate()))
380	            .count();
381	    }
