383	    /**
384	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
385	     * holiday is advanced one day at a time until a non-holiday weekday is reached, while a plain
386	     * weekday is returned unchanged. Applied to the effective registration date (whether supplied
387	     * or defaulted to the server date) so that the stored {@code registrationDate}, every value
388	     * derived from it (such as the membership number's year segment) and the per-day create-limit
389	     * all use the adjusted business day.
390	     */
391	    private static LocalDate toBusinessDay(LocalDate date) {
392	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
393	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
394	            || HOLIDAYS.contains(date)) {
395	            date = date.plusDays(1);
396	        }
397	        return date;
398	    }
