400	    @Override
401	    @Transactional(readOnly = true)
402	    public boolean isIdentityKeyInUse(Owner owner) throws DataAccessException {
403	        String identityKey = owner.getIdentityKey();
404	        return ownerRepository.findAll().stream()
405	            .filter(existing -> existing != owner)
406	            .filter(existing -> !existing.isDeleted())
407	            .map(Owner::getIdentityKey)
408	            .anyMatch(identityKey::equals);
409	    }
