411	    /**
412	     * Resolve the id of an existing owner that the given (not yet persisted) owner is a <em>possible</em>
413	     * duplicate of, or {@code null} when there is none. A possible duplicate belongs to an existing
414	     * owner's household (same computed {@code householdId}, i.e. same last name and postcode) while
415	     * carrying a different telephone, so it is not a hard duplicate (its identity key is unique) but is
416	     * worth flagging. When several existing owners match, the one with the lowest id is returned so the
417	     * result is deterministic. Computed once, at creation, to drive the read-only
418	     * {@code possibleDuplicate}/{@code possibleDuplicateOf} fields.
419	     */
420	    private Integer findPossibleDuplicateOf(Owner owner) {
421	        String householdId = owner.getHouseholdId();
422	        if (householdId == null) {
423	            return null;
424	        }
425	        return ownerRepository.findAll().stream()
426	            .filter(existing -> existing != owner && existing.getId() != null)
427	            .filter(existing -> !existing.isDeleted())
428	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
429	            .filter(existing -> !Objects.equals(owner.getTelephone(), existing.getTelephone()))
430	            .map(Owner::getId)
431	            .min(Integer::compareTo)
432	            .orElse(null);
433	    }
434	
435	    @Override
436	    @Transactional(readOnly = true)
437	    public boolean isHouseholdInUse(Owner owner) throws DataAccessException {
438	        String householdId = owner.getHouseholdId() != null
439	            ? owner.getHouseholdId()
440	            : householdIdFor(owner.getLastName(), owner.getPostcode());
441	        return ownerRepository.findAll().stream()
442	            .filter(existing -> existing != owner && existing.getId() != null)
443	            .filter(existing -> !existing.isDeleted())
444	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
445	    }
446	
447	    @Override
448	    @Transactional(readOnly = true)
449	    public String householdIdFor(String lastName, String postcode) throws DataAccessException {
450	        String key = normalizeHouseholdValue(lastName) + "|" + (postcode == null ? "" : postcode);
451	        return Sha256Hex.upperHexPrefix(key, 12);
452	    }
453	
454	    /**
455	     * Normalizes a household field (the last name) for duplicate comparison by trimming,
456	     * collapsing runs of whitespace to a single space and lower-casing, so differently cased or
457	     * spaced but equivalent values compare equal.
458	     */
459	    private static String normalizeHouseholdValue(String value) {
460	        if (value == null) {
461	            return "";
462	        }
463	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
464	    }
465	
466	    /**
467	     * Populate each given owner's transient {@code householdMemberCount} with the current number of
468	     * owners that share its {@code householdId}. Owners without a household id are left at a count
469	     * of zero.
470	     *
471	     * <p>The household sizes are computed in a single pass over the owner table regardless of how
472	     * many owners are being decorated, so decorating a whole page does not re-scan per element.
473	     */
474	    private <T> T decorateWithHouseholdMemberCount(T result, Collection<Owner> owners) {
475	        if (!owners.isEmpty()) {
476	            Map<String, Long> sizeByHousehold = ownerRepository.findAll().stream()
477	                .filter(owner -> owner.getHouseholdId() != null)
478	                .collect(Collectors.groupingBy(Owner::getHouseholdId, Collectors.counting()));
479	            for (Owner owner : owners) {
480	                long size = owner.getHouseholdId() == null
481	                    ? 0L
482	                    : sizeByHousehold.getOrDefault(owner.getHouseholdId(), 0L);
483	                owner.setHouseholdMemberCount((int) size);
484	            }
485	        }
486	        return result;
487	    }
488	
489	    /**
490	     * Decorate a single (possibly {@code null}) owner with its household member count and return it.
491	     */
492	    private Owner decorateWithHouseholdMemberCount(Owner owner) {
493	        return decorateWithHouseholdMemberCount(owner, owner == null ? List.of() : List.of(owner));
494	    }
