1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	
6	/**
7	 * Converts raw telephone input into canonical E.164 form.
8	 *
9	 * <p>The rules are:
10	 * <ul>
11	 *   <li>spaces, dashes and brackets are stripped;</li>
12	 *   <li>a leading {@code '+'} and country code are kept when present;</li>
13	 *   <li>otherwise the default country code {@code '+61'} is assumed and a single
14	 *       leading {@code '0'} is dropped from the national digits;</li>
15	 *   <li>the result must contain between 8 and 15 digits after the {@code '+'};</li>
16	 *   <li>for a recognised country code the national number (the digits after the
17	 *       country code) must have the exact length that country requires:
18	 *       {@code '+61'} requires 9 national digits and {@code '+1'} requires 10.</li>
19	 * </ul>
20	 *
21	 * <p>So {@code '0412 345 678'} becomes {@code '+61412345678'} and
22	 * {@code '+64 21 123 456'} becomes {@code '+6421123456'}.
23	 */
24	public final class TelephoneNormalizer {
25	
26	    private static final String DEFAULT_COUNTRY_CODE = "61";
27	
28	    /**
29	     * Known country codes mapped to the exact number of national digits they require.
30	     * Ordered longest-code-first so the most specific prefix wins when matching.
31	     */
32	    private static final Map<String, Integer> NATIONAL_LENGTHS = new LinkedHashMap<>();
33	
34	    static {
35	        NATIONAL_LENGTHS.put(DEFAULT_COUNTRY_CODE, 9);
36	        NATIONAL_LENGTHS.put("1", 10);
37	    }
38	
39	    private TelephoneNormalizer() {
40	    }
41	
42	    /**
43	     * Convert a raw telephone number to canonical E.164 form.
44	     *
45	     * @param raw the telephone number as supplied by the caller (any format)
46	     * @return the E.164 string (a leading {@code '+'} followed by 8-15 digits), or
47	     *         {@code null} if {@code raw} is {@code null}
48	     * @throws InvalidTelephoneException if {@code raw} cannot form a valid E.164 number
49	     */
50	    public static String toE164(String raw) {
51	        if (raw == null) {
52	            return null;
53	        }
54	        // Strip spaces, dashes and brackets.
55	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
56	        String digits;
57	        if (cleaned.startsWith("+")) {
58	            // Keep the explicit country code.
59	            digits = cleaned.substring(1);
60	        } else {
61	            // Assume the default country code and drop a single leading '0'.
62	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
63	            digits = DEFAULT_COUNTRY_CODE + national;
64	        }
65	        if (!digits.matches("\\d{8,15}")) {
66	            throw new InvalidTelephoneException(raw);
67	        }
68	        assertNationalLength(digits, raw);
69	        return "+" + digits;
70	    }
71	
72	    /**
73	     * Format a canonical E.164 number for human display: the country code (with its leading
74	     * {@code '+'}), a space, then the national digits grouped left-to-right in threes and
75	     * space-separated. For a recognised country code the national number is the digits after
76	     * that code (country codes are matched longest-first so the most specific prefix wins);
77	     * for an unrecognised code the whole digit sequence is grouped in threes. So
78	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}.
79	     *
80	     * @param e164 a canonical E.164 string (a leading {@code '+'} followed by 8-15 digits), or
81	     *             {@code null}
82	     * @return the display string, or {@code null} if {@code e164} is {@code null}
83	     */
84	    public static String toDisplay(String e164) {
85	        if (e164 == null) {
86	            return null;
87	        }
88	        String digits = e164.startsWith("+") ? e164.substring(1) : e164;
89	        for (String countryCode : NATIONAL_LENGTHS.keySet()) {
90	            if (digits.startsWith(countryCode) && digits.length() > countryCode.length()) {
91	                return "+" + countryCode + " " + groupInThrees(digits.substring(countryCode.length()));
92	            }
93	        }
94	        return "+" + groupInThrees(digits);
95	    }
96	
97	    /**
98	     * Group a run of digits left-to-right into space-separated chunks of three (a trailing chunk
99	     * may have one or two digits). So {@code '412345678'} becomes {@code '412 345 678'}.
100	     */
101	    private static String groupInThrees(String digits) {
102	        StringBuilder sb = new StringBuilder();
103	        for (int i = 0; i < digits.length(); i++) {
104	            if (i > 0 && i % 3 == 0) {
105	                sb.append(' ');
106	            }
107	            sb.append(digits.charAt(i));
108	        }
109	        return sb.toString();
110	    }
111	
112	    /**
113	     * Verify that, for a recognised country code, the national number (the digits following the
114	     * country code) has exactly the length that country requires. Country codes are matched
115	     * longest-first so the most specific prefix wins. Unrecognised country codes are left to the
116	     * generic 8-15 digit range check.
117	     *
118	     * @param digits the E.164 digits (no leading {@code '+'})
119	     * @param raw    the original caller input, used only for the rejection message
120	     * @throws InvalidTelephoneException if the national number has the wrong length for its country
121	     */
122	    private static void assertNationalLength(String digits, String raw) {
123	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTHS.entrySet()) {
124	            String countryCode = entry.getKey();
125	            if (digits.startsWith(countryCode)) {
126	                int nationalLength = digits.length() - countryCode.length();
127	                if (nationalLength != entry.getValue()) {
128	                    throw new InvalidTelephoneException(raw);
129	                }
130	                return;
131	            }
132	        }
133	    }
134	}
