17	package org.springframework.samples.petclinic.service;
18	
19	import java.util.Map;
20	import java.util.Optional;
21	import java.util.concurrent.ConcurrentHashMap;
22	
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Remembers the owner that was created for a given {@code Idempotency-Key}, so a repeated
27	 * create carrying the same key can return the originally created owner instead of creating
28	 * a duplicate.
29	 *
30	 * <p>The mapping is kept in memory for the lifetime of the application; keys are supplied by
31	 * the client and are treated opaquely.
32	 */
33	@Component
34	public class IdempotencyKeyRegistry {
35	
36	    private final Map<String, Integer> keyToOwnerId = new ConcurrentHashMap<>();
37	
38	    /**
39	     * Returns the id of the owner previously created for the given key, if any.
40	     *
41	     * @param key the idempotency key (may be {@code null} or blank, in which case nothing is found)
42	     * @return the previously created owner id, or empty if the key has not been seen
43	     */
44	    public Optional<Integer> findOwnerId(String key) {
45	        if (key == null || key.isBlank()) {
46	            return Optional.empty();
47	        }
48	        return Optional.ofNullable(this.keyToOwnerId.get(key));
49	    }
50	
51	    /**
52	     * Records that the given key produced the owner with the given id. No-op for a blank key.
53	     *
54	     * @param key     the idempotency key supplied with the create request
55	     * @param ownerId the id of the owner that was created
56	     */
57	    public void remember(String key, Integer ownerId) {
58	        if (key == null || key.isBlank() || ownerId == null) {
59	            return;
60	        }
61	        this.keyToOwnerId.putIfAbsent(key, ownerId);
62	    }
63	}
